//! Explicit opt-in native display-view processing, no project output/default edits.
use super::kit::*;
pub fn commands()->Vec<Command>{vec![
 Command{name:"transform_ocio_view_samples",description:"Forward native OCIO display-view CPU pipeline including configured looks. Up to4096 RGBA samples in explicitly named source space. No project mutation, external LUTs or display calibration.",mutates:false,
 schema:obj(vec![("config_path",s("self-contained config")),("source",s("declared source colorspace")),("display",s("exact listed display")),("view",s("exact listed attached view")),("rgba",json!({"type":"array","items":{"type":"number"}}))],&["config_path","source","display","view","rgba"]),run:|_,a|{
 #[cfg(not(feature="native-ocio"))]{let _=a;Err("requires native-ocio feature and OCIO2 library".into())}
 #[cfg(feature="native-ocio")]{let v=a.get("rgba").and_then(Value::as_array).ok_or("RGBA array required")?;if v.is_empty()||v.len()%4!=0||v.len()>16384{return Err("need1..4096 RGBA samples".into())}let d=v.iter().map(|v|v.as_f64().filter(|n|n.is_finite()).map(|n|n as f32).ok_or("finite RGBA numbers required".to_string())).collect::<Result<Vec<_>,_>>()?;let mut f=crate::effects::Frame{w:d.len()/4,h:1,d};crate::color::frame::validate(&f)?;let c=crate::color::ocio_config::Config::from_file(str_arg(a,"config_path")?)?;c.display_processor(str_arg(a,"source")?,str_arg(a,"display")?,str_arg(a,"view")?)?.apply(&mut f)?;Ok(json!({"rgba":f.d,"ocio_version":crate::color::ocio_config::version(),"display":str_arg(a,"display")?,"view":str_arg(a,"view")?,"direction":"forward","looks_bypassed":false,"alpha_preserved":true}))}
 }},
 Command{name:"render_ocio_display_view",description:"Render managed AP1 scene-linear frame through selected native OCIO display-view pipeline, including looks. Caller declares output SDR sRGB for PNG preview. Bypasses project output transform; no defaults/project mutation, no HDR/display calibration.",mutates:false,
 schema:obj(vec![("config_path",s("self-contained config")),("source",s("config space representing AP1/D60 scene-linear pixels")),("display",s("exact display")),("view",s("exact attached view")),("time",n("timeline seconds")),("path",s("SDR sRGB PNG")),("output_encoding",json!({"type":"string","enum":["sRGB_SDR"]}))],&["config_path","source","display","view","time","path","output_encoding"]),run:|ss,a|{
 #[cfg(not(feature="native-ocio"))]{let _=(ss,a);Err("requires native-ocio feature and OCIO2 library".into())}
 #[cfg(feature="native-ocio")]{let q=&ss.project.color_pipeline;if !q.enabled||q.working_gamut!=3{return Err("display-view preview requires managed AP1/D60 scene-linear working_gamut3".into())}let path=str_arg(a,"path")?;if !path.to_lowercase().ends_with(".png")||str_arg(a,"output_encoding")?!="sRGB_SDR"{return Err("requires PNG and caller-declared sRGB_SDR view output".into())}let c=crate::color::ocio_config::Config::from_file(str_arg(a,"config_path")?)?;let p=c.display_processor(str_arg(a,"source")?,str_arg(a,"display")?,str_arg(a,"view")?)?;let t=num_arg(a,"time")?;let mut cache=crate::render::Cache::new();crate::render::prepare_at(&ss.project,&mut cache,Some(t))?;let mut f=crate::render::render_frame(&ss.project,t,&cache)?;p.apply(&mut f)?;let clipped=f.d.chunks_exact(4).filter(|p|p[..3].iter().any(|v|*v<0.||*v>1.)).count();crate::render::write_image(&f,path)?;Ok(json!({"path":path,"source":str_arg(a,"source")?,"display":str_arg(a,"display")?,"view":str_arg(a,"view")?,"ocio_version":crate::color::ocio_config::version(),"configured_project_output_applied":false,"looks_bypassed":false,"png_out_of_range_pixels":clipped,"note":"Caller declares config source AP1/D60 scene-linear and view sRGB SDR output. PNG quantizes/clips0..1. No hardware display or ACES certification."}))}
 }}
]}
